<template><el-dialog title="门诊收费凭证" :visible="!!receipt" width="660px" @close="$emit('close')"><div v-if="receipt" id="receipt-paper"><div class="receipt-heading"><h2>云医院门诊收费凭证</h2><p>单据号 {{ receipt.receipt_no }}</p></div><div class="info-grid"><span>患者：{{receipt.patient_name}}</span><span>病历号：{{receipt.case_no}}</span><span>收费员：{{receipt.cashier_name}}</span><span>支付方式：{{receipt.pay_method}}</span></div><el-table :data="receipt.lines"><el-table-column prop="item_name" label="收费项目"/><el-table-column prop="quantity" label="数量" width="70"/><el-table-column label="金额" width="110"><template slot-scope="s">{{money(s.row.amount_cents)}}</template></el-table-column><el-table-column label="费用状态" width="100"><template slot-scope="s">{{label(s.row.billing_status)}}</template></el-table-column></el-table><div class="receipt-totals"><p>应收：<b>{{money(receipt.total_cents)}}</b></p><p>实收：{{money(receipt.received_cents)}}　找零：{{money(receipt.change_cents)}}</p><p>时间：{{date(receipt.created_at)}}</p></div><p class="muted">本凭证为院内业务收款记录，正式税务发票需对接医院发票平台。</p></div><span slot="footer"><el-button @click="$emit('close')">关闭</el-button><el-button type="primary" @click="print">打印凭证</el-button></span></el-dialog></template>
<script>import {money,label,date} from '../api';export default{props:['receipt'],methods:{money,label,date,print(){window.print();}}};</script>
